source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    tile = 4
    step = tile + 1
    bands = (h + 1) // step
    cols = (w + 1) // step

    # The first tile in each band carries that band's output color.
    colors = []
    for band in range(bands):
        r0 = band * step
        found = {grid[r0 + r][c] for r in range(tile) for c in range(tile) if grid[r0 + r][c] not in (0,)}
        # Ignore the grid separators (they are outside tile coordinates).
        colors.append(min(found))

    # A single non-marker tile contains the pattern to replicate.
    pattern = None
    for band in range(bands):
        for col in range(1, cols):
            r0, c0 = band * step, col * step
            cells = [[grid[r0+r][c0+c] for c in range(tile)] for r in range(tile)]
            occupied = [(r, c, cells[r][c]) for r in range(tile) for c in range(tile) if cells[r][c] != 0]
            if occupied:
                pattern = {(r, c) for r, c, _ in occupied}
                break
        if pattern is not None:
            break
    if pattern is None:
        return [row[:] for row in grid]

    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if r % step == tile or c % step == tile:
                out[r][c] = grid[r][c]
    for band in range(bands):
        for col in range(cols):
            r0, c0 = band * step, col * step
            for r, c in pattern:
                out[r0+r][c0+c] = colors[band]
    return out
'''
